using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef std::pair<int,int> pii;

#ifdef DBG1
    #define dbg(...) fprintf(stderr, __VA_ARGS__), fflush(stderr)
#else
    #define dbg(...)
#endif

const ll P = ll(1e9) + 7;

struct Matrix {
    static const int N = 33;
    int n;
    ll a[N][N];

    Matrix(int n = 0, int k = 0) : n(n) {
        memset(a, 0, sizeof(a));
        for (int i = 0; i < n; ++i) {
            a[i][i] = k;
        }
    }

    Matrix operator * (const Matrix & m) const {
        assert(n == m.n);
        Matrix res(n);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int k = 0; k < n; ++k) {
                    (res.a[i][k] += a[i][j] * m.a[j][k]) %= P;
                }
            }
        }
        return res;
    }

    Matrix& operator *= (const Matrix & m) {
        return *this = *this * m;
    }

    Matrix pow(int x) const {
        Matrix res = Matrix(n, 1);
        Matrix a = *this;
        while (x) {
            if (x & 1) {
                res *= a;
            }
            a *= a;
            x /= 2;
        }
        return res;
    }

    void print() const {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                dbg("%d ", int(a[i][j]));
            }
            dbg("\n");
        }
        dbg("\n");
    }

    ll* operator[](int index) {
        return a[index];
    }

    const ll* operator[](int index) const {
        return a[index];
    }
};

int main()
{
#ifdef DBG1
    freopen(".in", "r", stdin);
    freopen(".out", "w", stdout);
    freopen(".err", "w", stderr);
#endif

    ll n;
    int k;
    cin >> n >> k;
    if (n <= k) {
        cout << (1LL << n) % P << endl;
        return 0;
    }

    int logN = int(log(n + 0.0) / log(k + 0.0) + 2);

    Matrix shift(k + 1, 1);
    for (int j = 0; j < k; ++j) {
        shift[j][j] = 0;
        shift[(j + 1) % k][j] = 1;
    }
    vector <Matrix> block(logN);
    block[0] = Matrix(k + 1, 1);
    for (int i = 1; i <= k; ++i) {
        block[0][0][i] = 1;
    }
    for (int i = 1; i < logN; ++i) {
        block[i] = (block[i - 1] * shift).pow(k);
    }

    int i = 0;
    ll len = 1;
    while (n / len >= k) {
        i++;
        len *= k;
    }

    Matrix m(k + 1, 1);
    while (n) {
        if (len <= n) {
            int x = int(n / len);
            m *= (block[i] * shift).pow(x);
            n -= len * x;
        }
        --i;
        len /= k;
    }

    ll ans = 0;
    for (int i = 0; i <= k; ++i) {
        (ans += m[i][k]) %= P;
    }
    cout << ans << endl;

    return 0;
}

